/** AppleCalendarSource — reads a bounded day from EventKit through Stone's
 * signed native bridge. EventKit avoids the per-object Apple Events traffic
 * generated by Calendar.app scripting and owns the macOS Calendar prompt. */

import { execFile } from 'node:child_process';
import type { CalendarEvent, ICalendarSource } from '../../../domain/ports/out/ICalendarSource';
import type { ExternalSourceResult } from '../../../domain/ports/out/externalSourceResult';
import { logger } from '../../../shared/utils';

interface RawEvent {
  title?: string;
  start?: string;
  end?: string;
  allDay?: boolean;
  calendar?: string;
  location?: string | null;
}

interface BridgeResponse {
  status?: ExternalSourceResult<CalendarEvent[]>['status'];
  data?: RawEvent[];
  message?: string;
}

export class AppleCalendarSource implements ICalendarSource {
  constructor(private readonly bridgePath: string) {}

  async getEventsForDate(date: string): Promise<ExternalSourceResult<CalendarEvent[]>> {
    if (process.platform !== 'darwin') {
      return { status: 'unavailable', data: [], message: 'Available on macOS only.' };
    }
    const result = await runBridge(this.bridgePath, date);
    return result;
  }
}

function runBridge(
  bridgePath: string,
  date: string,
): Promise<ExternalSourceResult<CalendarEvent[]>> {
  return new Promise((resolve) => {
    execFile(bridgePath, [date], { timeout: 30_000, maxBuffer: 1024 * 1024 }, (error, stdout) => {
      if (error) {
        logger.warn('[CalendarBridge] request failed', {
          code: error.code ?? null,
          killed: Boolean(error.killed),
        });
        resolve({
          status: error.killed ? 'error' : 'unavailable',
          data: [],
          message: error.killed
            ? 'Calendar permission was not completed in time.'
            : 'The Calendar connection is unavailable.',
        });
        return;
      }

      try {
        const response = JSON.parse(stdout.trim()) as BridgeResponse;
        const status = response.status ?? 'error';
        const events = Array.isArray(response.data) ? response.data : [];
        resolve({
          status,
          data: events.map((event) => ({
            title: String(event.title ?? '(no title)'),
            start: String(event.start ?? ''),
            end: String(event.end ?? ''),
            allDay: Boolean(event.allDay),
            calendar: String(event.calendar ?? ''),
            location: event.location ? String(event.location) : null,
          })),
          ...(response.message ? { message: response.message } : {}),
        });
      } catch {
        resolve({ status: 'error', data: [], message: 'Calendar returned invalid data.' });
      }
    });
  });
}
